12-weather-outfitters.myshopify.com.css:
/* Guard: no sideways pan on phone/tablet */
html, body { overflow-x: clip; }
/* Phone header: logo collides with the EN locale picker -> drop locale + help icons */
@media (max-width: 480px) {
  .header__right .locale-selector, .header__right .help-menu { display: none !important; }
}
/* Search grid overflows (grid--4 never collapses; 1fr tracks grow to image min-content) */
.shop-main { min-width: 0; }
#shop-grid.grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
@media (min-width: 768px) { #shop-grid.grid--4 { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; } }
@media (min-width: 1100px) { #shop-grid.grid--4 { grid-template-columns: repeat(4, minmax(0, 1fr)) !important; } }
/* Home: "New Arrivals" section renders a heading over an EMPTY grid (big blank band) */
.shopify-section:has(.section__header):has(.grid):not(:has(.grid > *)) { display: none !important; }
/* Phone PDP: sticky add-to-bag bar sits under the Bizmis widget bar */
@media (max-width: 767px) { .mobile-sticky-atb { display: none !important; } }
/* Hero split: white 4px gutter cuts through the transparent nav ("MEN" sliced) */
.image-split { background: #101418; }
.header--transparent { background: linear-gradient(to bottom, rgba(16,20,24,.45), rgba(16,20,24,0)); }
/* Card hover turns title brand-yellow on cream (unreadable) */
.product-card:hover .product-card__title { color: inherit !important; }
/* Phone search page: SEARCH pill clipped at the right edge (input min-width:auto + 36px button padding) */
.search-form .search-form__input { min-width: 0 !important; }
@media (max-width: 480px) { .search-form .btn { padding-left: 20px !important; padding-right: 20px !important; flex-shrink: 0; } }

meridian-consumer-electronics.myshopify..css:
/* 28px blank band above the header (--promo-height reserved for an absent promo bar); content shows through it when scrolled */
html, body { --promo-height: 0px !important; }
html, body { overflow-x: clip; }
/* Visible coloured page scrollbar on the right edge (OverlayScrollbars .os-scrollbar, brand-tinted) */
.os-scrollbar { opacity: 0 !important; visibility: hidden !important; }
html, body { scrollbar-width: none; }
/* Phone: hover action bar on cards is cramped (Quick View text clipped) and sticks on the first card */
@media (max-width: 749px) { .product-card__actions { display: none !important; } }
/* Phone/tablet PDP: sticky price + add-to-cart bar sits under the Bizmis widget bar */
@media (max-width: 989px) { .pdp-sticky-bar { display: none !important; } }
/* Header background/border only spans the 1280px container -> boxed header with off-colour gutters */
.header:not(.is-transparent) .header__primary { background: rgba(255,255,255,.92); backdrop-filter: blur(20px); border-bottom: 1px solid var(--color-border); }
.header__primary > .page-width { border-bottom-color: transparent !important; }

/* v9: Bizmis is a sales agent, not a clerk: 'The store clerk is in.' reads 'The sales agent is in.' (same word lengths, swapped in place) */
.hero__title-line > .hero__word:nth-child(2), .hero__title-line > .hero__word:nth-child(3) { display: inline-grid !important; grid-template-rows: auto; grid-auto-rows: 0; overflow: visible; -webkit-text-fill-color: transparent; }
.hero__title-line > .hero__word:nth-child(2)::after, .hero__title-line > .hero__word:nth-child(3)::after { grid-area: 1 / 1; -webkit-text-fill-color: currentColor; white-space: nowrap; }
.hero__title-line > .hero__word:nth-child(2)::after { content: 'sales'; }
.hero__title-line > .hero__word:nth-child(3)::after { content: 'agent'; }

/* v9: the in-store 'Talk to the store clerk / Install Bizmis' block is our pitch, not the merchant's */
section.hero-voice { display: none !important; }

paper-and-pine-books.myshopify.com.css:
/* Phone: page is 15-27px wider than the viewport (sideways pan) */
html, body { overflow-x: clip; }
/* Phone search: SEARCH button pushed past the right edge (input min-width:auto won't shrink) */
.search-form__input, main form[action*="search"] input { min-width: 0 !important; }
main form[action*="search"] button { flex-shrink: 0; }
/* Phone footer: newsletter grid column (351px) wider than the viewport -> SUBSCRIBE button runs off the right edge */
@media (max-width: 749px) {
  .footer__newsletter-inner { grid-template-columns: minmax(0, 1fr) !important; }
  .footer__newsletter-input { min-width: 0 !important; width: 100% !important; }
  .footer__newsletter-form .btn { flex-shrink: 0; }
}

